  "promos": [
    {
      "title": "The Soldier's Vow",
      "start_block": "B016",
      "end_block": "B029",
      "hook": "Close-up of Alexander's scarred face, his piercing blue-grey eyes fixed with absolute conviction as he says, 'I would do it again.'",
      "cliffhanger": "Their joined hands — his scarred fingers wrapping around her bandaged fingers — as he squeezes reassuringly and the scene fades to black.",
      "why": "Starts on a fierce protective vow, builds through escalating devotion, and cuts on the intimate hand-hold before any resolution.",
      "context_gap": "A stranger would not know Alexander just fought off hired thugs sent by Gerald."
    },
    {
      "title": "Fear of Losing You",
      "start_block": "B040",
      "end_block": "B054",
      "hook": "Juliana looks up at Alexander in the warm amber glow, her vulnerability resurfacing as she whispers, 'I was frightened.'",
      "cliffhanger": "The couple embraced in front of the roaring fireplace, Alexander's arms wrapped around her shoulders, holding her safe against his frame.",
      "why": "Emotional confession escalates from fear to a tender embrace, ending on the visual of them locked together before any further dialogue.",
      "context_gap": "A stranger would not know why Juliana fears losing him or the danger they faced the night before."
    },
    {
      "title": "Every Day I Trust Him",
      "start_block": "B063",
      "end_block": "B075",
      "hook": "Juliana lifts her bandaged hand toward Alexander's beard playfully, teasing, 'Then I shall have to save you from the birds.'",
      "cliffhanger": "Slow pull-back wide shot of Alexander and Juliana locked in a tender embrace before the radiant hearth as her voiceover says, 'But every day, he gives me another reason to trust him.'",
      "why": "Ends on the episode's final beat — a loving voiceover over their embrace — leaving the emotional arc unresolved and inviting the viewer to see what happens next.",
      "context_gap": "A stranger would not know Alexander's secret identity or why Juliana knows 'almost nothing' about him."
    }
  ],
  "moments": [
    {
      "start_block": "B016",
      "end_block": "B023",
      "kind": "hook",
      "description": "Alexander vows to Juliana that no one will hurt her again, dropping to one knee and taking her bandaged hands."
    },
    {
      "start_block": "B044",
      "end_block": "B046",
      "kind": "emotional",
      "description": "Juliana whispers she was frightened of losing Alexander, and his gaze softens with profound emotion."
    },
    {
      "start_block": "B051",
      "end_block": "B053",
      "kind": "emotional",
      "description": "Juliana notices Alexander's racing heart as they embrace, and he whispers back, 'So is yours.'"
    },
    {
      "start_block": "B072",
      "end_block": "B074",
      "kind": "cliffhanger",
      "description": "Juliana's voiceover reveals she knows almost nothing about the man she married but trusts him more every day, over their embrace."
    }
  ]
}
